mapper.select:
SELECT id, homework_id AS homeworkId, student_id AS studentId, question_id AS questionId,
       key_points AS keyPoints, error_analysis AS errorAnalysis, steps, expansion,
       reference_code AS referenceCode, common_mistakes AS commonMistakes,
       version, create_time AS createTime, duration, is_cache_hit AS isCacheHit
FROM ai_explain_log 
WHERE homework_id = #{homeworkId} 
AND student_id = #{studentId} 
AND question_id = #{questionId}
AND version = #{version}
AND create_time > DATE_SUB(NOW(), INTERVAL 30 DAY)
ORDER BY create_time DESC LIMIT 1

